Here is the commit message:
drm/gud: fix NULL fb and crtc dereferences on USB disconnect

On disconnect drm_atomic_helper_disable_all() is called which
sets both the fb and crtc for a plane to NULL before invoking a commit.

This causes a kernel oops on every display disconnect.

Add guards for those dereferences.

Cc: <stable@vger.kernel.org> # 6.18.x
Fixes: 73cfd166e045 ("drm/gud: Replace simple display pipe with DRM atomic helpers")
Signed-off-by: Shenghao Yang <me@shenghaoyang.info>
Reviewed-by: Ruben Wauters <rubenru09@aol.com>
Signed-off-by: Ruben Wauters <rubenru09@aol.com>
Link: https://patch.msgid.link/20251231055039.44266-1-me@shenghaoyang.info

Here is the root cause:
The bug occurs because the gud_plane_atomic_check and gud_plane_atomic_update functions in the GUD driver assume that the crtc and fb pointers in a plane state are always non-NULL during atomic check/update. However, when a USB display is disconnected, drm_atomic_helper_disable_all() sets both the fb and crtc for a plane to NULL before invoking a commit. The absence of NULL pointer guards leads to a kernel oops by dereferencing these NULL pointers.

Here is the patch:

 int gud_plane_atomic_check(struct drm_plane *plane,
 			   struct drm_atomic_state *state)
 {
 	struct gud_device *gdrm = to_gud_device(plane->dev);
 	struct drm_plane_state *old_plane_state = drm_atomic_get_old_plane_state(state, plane);
 	struct drm_plane_state *new_plane_state = drm_atomic_get_new_plane_state(state, plane);
 	struct drm_crtc *crtc = new_plane_state->crtc;
-	struct drm_crtc_state *crtc_state;
+	struct drm_crtc_state *crtc_state = NULL;
 	const struct drm_display_mode *mode;
 	struct drm_framebuffer *old_fb = old_plane_state->fb;
 	struct drm_connector_state *connector_state = NULL;
 	struct drm_framebuffer *fb = new_plane_state->fb;
-	const struct drm_format_info *format = fb->format;
+	const struct drm_format_info *format;
 	struct drm_connector *connector;
 	unsigned int i, num_properties;
 	struct gud_state_req *req;
 	int idx, ret;
 	size_t len;

-	if (drm_WARN_ON_ONCE(plane->dev, !fb))
-		return -EINVAL;
-
-	if (drm_WARN_ON_ONCE(plane->dev, !crtc))
-		return -EINVAL;
-
-	crtc_state = drm_atomic_get_new_crtc_state(state, crtc);
-
-	mode = &crtc_state->mode;
+	if (crtc)
+		crtc_state = drm_atomic_get_new_crtc_state(state, crtc);

 	ret = drm_atomic_helper_check_plane_state(new_plane_state, crtc_state,
 						  DRM_PLANE_NO_SCALING,
 						  DRM_PLANE_NO_SCALING,
 						  false, false);
 	if (ret)
 		return ret;

 	if (!new_plane_state->visible)
 		return 0;

 	if (old_plane_state->rotation != new_plane_state->rotation)
 		crtc_state->mode_changed = true;

+	mode = &crtc_state->mode;
+	format = fb->format;
+
 	if (old_fb && old_fb->format != format)
 		crtc_state->mode_changed = true;

 	if (!crtc_state->mode_changed && !crtc_state->connectors_changed)
 		return 0;

 	/* Only one connector is supported */
 	if (hweight32(crtc_state->connector_mask) != 1)
 		return -EINVAL;

 	if (format->format == DRM_FORMAT_XRGB8888 && gdrm->xrgb8888_emulation_format)
 		format = gdrm->xrgb8888_emulation_format;

 	for_each_new_connector_in_state(state, connector, connector_state, i) {
 		if (connector_state->crtc)
 			break;
 	}

 	/*
 	 * DRM_IOCTL_MODE_OBJ_SETPROPERTY on the rotation property will not have
 	 * the connector included in the state.
 	 */
 	if (!connector_state) {
 		struct drm_connector_list_iter conn_iter;

 		drm_connector_list_iter_begin(plane->dev, &conn_iter);
 		drm_for_each_connector_iter(connector, &conn_iter) {
 			if (connector->state->crtc) {
 				connector_state = connector->state;
 				break;
 			}
 		}
 		drm_connector_list_iter_end(&conn_iter);
 	}

 	if (drm_WARN_ON_ONCE(plane->dev, !connector_state))
 		return -ENOENT;

 	len = struct_size(req, properties,
 			  size_add(GUD_PROPERTIES_MAX_NUM, GUD_CONNECTOR_PROPERTIES_MAX_NUM));
 	req = kzalloc(len, GFP_KERNEL);
 	if (!req)
 		return -ENOMEM;

 	gud_from_display_mode(&req->mode, mode);

 	req->format = gud_from_fourcc(format->format);
 	if (drm_WARN_ON_ONCE(plane->dev, !req->format)) {
 		ret = -EINVAL;
 		goto out;
 	}

 	req->connector = drm_connector_index(connector_state->connector);

 	ret = gud_connector_fill_properties(connector_state, req->properties);
 	if (ret < 0)
 		goto out;

 	num_properties = ret;
 	for (i = 0; i < gdrm->num_properties; i++) {
 		u16 prop = gdrm->properties[i];
 		u64 val;

 		switch (prop) {
 		case GUD_PROPERTY_ROTATION:
 			/* DRM UAPI matches the protocol so use value directly */
 			val = new_plane_state->rotation;
 			break;
 		default:
 			drm_WARN_ON_ONCE(plane->dev, 1);
 			ret = -EINVAL;
 			goto out;
 		}

 		req->properties[num_properties + i].prop = cpu_to_le16(prop);
 		req->properties[num_properties + i].val = cpu_to_le64(val);
 		num_properties++;
 	}

 	if (drm_dev_enter(fb->dev, &idx)) {
 		len = struct_size(req, properties, num_properties);
 		ret = gud_usb_set(gdrm, GUD_REQ_SET_STATE_CHECK, 0, req, len);
 		drm_dev_exit(idx);
 	}  else {
 		ret = -ENODEV;
 	}
 out:
 	kfree(req);

 	return ret;
 }

 void gud_plane_atomic_update(struct drm_plane *plane,
 			     struct drm_atomic_state *atomic_state)
 {
 	struct drm_device *drm = plane->dev;
 	struct gud_device *gdrm = to_gud_device(drm);
 	struct drm_plane_state *old_state = drm_atomic_get_old_plane_state(atomic_state, plane);
 	struct drm_plane_state *new_state = drm_atomic_get_new_plane_state(atomic_state, plane);
 	struct drm_shadow_plane_state *shadow_plane_state = to_drm_shadow_plane_state(new_state);
 	struct drm_framebuffer *fb = new_state->fb;
 	struct drm_crtc *crtc = new_state->crtc;
 	struct drm_rect damage;
 	struct drm_atomic_helper_damage_iter iter;
 	int ret, idx;

-	if (crtc->state->mode_changed || !crtc->state->enable) {
+	if (!crtc || crtc->state->mode_changed || !crtc->state->enable) {
 		cancel_work_sync(&gdrm->work);
 		mutex_lock(&gdrm->damage_lock);
 		if (gdrm->fb) {
 			drm_framebuffer_put(gdrm->fb);
 			gdrm->fb = NULL;
 		}
 		gud_clear_damage(gdrm);
 		vfree(gdrm->shadow_buf);
 		gdrm->shadow_buf = NULL;
 		mutex_unlock(&gdrm->damage_lock);
 	}

 	if (!drm_dev_enter(drm, &idx))
 		return;

 	if (!old_state->fb)
 		gud_usb_set_u8(gdrm, GUD_REQ_SET_CONTROLLER_ENABLE, 1);

 	if (fb && (crtc->state->mode_changed || crtc->state->connectors_changed))
 		gud_usb_set(gdrm, GUD_REQ_SET_STATE_COMMIT, 0, NULL, 0);

 	if (crtc->state->active_changed)
 		gud_usb_set_u8(gdrm, GUD_REQ_SET_DISPLAY_ENABLE, crtc->state->active);

 	if (!fb)
 		goto ctrl_disable;

 	ret = drm_gem_fb_begin_cpu_access(fb, DMA_FROM_DEVICE);
 	if (ret)
 		goto ctrl_disable;

 	drm_atomic_helper_damage_iter_init(&iter, old_state, new_state);
 	drm_atomic_for_each_plane_damage(&iter, &damage)
 		gud_fb_handle_damage(gdrm, fb, &shadow_plane_state->data[0], &damage);

 	drm_gem_fb_end_cpu_access(fb, DMA_FROM_DEVICE);

 ctrl_disable:
 	if (!crtc->state->enable)
 		gud_usb_set_u8(gdrm, GUD_REQ_SET_CONTROLLER_ENABLE, 0);

 	drm_dev_exit(idx);
 }
